    tls: Arc<ServerConfig>,
    requests: SyncSender<RemoteIncoming>,
    frames: SyncSender<SubscriberFrame>,
    wake: Arc<dyn Fn() + Send + Sync>,
    pools: Pools,
    limits: Limits,
    next_subscriber: AtomicU64,
}

